# Linguística — lote L16
Q = []
TAILS=[" Essa seria a posição predominante na literatura linguística.",
 " Trata-se de entendimento consolidado na literatura linguística contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características do fenômeno descrito.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.95*len(C) and gap > 8: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"doutrina linguística; Manual de Redação da Presidência; LC 95/1998","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"LC 95/1998; Manual de Redação da Presidência","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def G(i,padE,dif,C,E,com,terro,lei=False):
    _n[i]=_n.get(i,0)+1
    P(f"L{i:02d}",[str(i)],"conceito_correto",padE,dif,C,E,com,terro,f"l{i:02d}{_n[i]}",lei=lei)
# ---- 1 signo
G(1,"confusao_instituto",2,"Para Saussure, a língua é um sistema social, abstrato e convencional, compartilhado pela comunidade, ao passo que a fala é o uso individual, concreto e momentâneo desse sistema.","Para Saussure, a língua é o uso individual, concreto e momentâneo do sistema, ao passo que a fala é um sistema social, abstrato e convencional, compartilhado pela comunidade.","Saussure, Curso de Linguística Geral.","inverte língua e fala")
G(1,"confusao_instituto",2,"O signo linguístico saussuriano resulta da união entre um significante, que é a imagem acústica, e um significado, que é o conceito.","O signo linguístico saussuriano resulta da união entre um significante, que é o conceito, e um significado, que é a imagem acústica.","Saussure, signo.","inverte significante e significado")
G(1,"excecao_omitida",3,"A arbitrariedade do signo significa que não existe laço natural entre o significante e o significado, o que se evidencia pelo fato de conceitos iguais serem designados por sequências sonoras diferentes em línguas diferentes.","A arbitrariedade do signo significa que cada falante escolhe livremente, em cada situação, o significante de que quer se servir, podendo alterá-lo por decisão individual.","Arbitrariedade.","confunde arbitrariedade com livre escolha individual")
G(1,"confusao_instituto",3,"A linearidade do significante decorre de sua natureza auditiva: desenvolve-se no tempo, em uma só dimensão, e seus elementos aparecem um após o outro, formando uma cadeia.","A linearidade do significante decorre de ele ser visual: seus elementos aparecem simultaneamente em múltiplas dimensões, o que impede a formação de uma cadeia.","Linearidade.","inverte natureza do significante")
G(1,"excecao_omitida",4,"Saussure admite a existência de arbitrariedade relativa, pois palavras derivadas e compostas, como 'dezenove' e 'pereira', são relativamente motivadas por sua relação com outros signos da língua.","Saussure sustenta que a arbitrariedade é absoluta em todos os signos, de modo que nenhum signo, nem mesmo os derivados e compostos, mantém qualquer motivação relativa.","Arbitrariedade relativa.","nega motivação relativa")
G(1,"confusao_instituto",3,"A sincronia estuda o estado de uma língua em determinado momento, ao passo que a diacronia estuda sua evolução ao longo do tempo.","A sincronia estuda a evolução de uma língua ao longo do tempo, ao passo que a diacronia estuda o estado da língua em determinado momento.","Sincronia e diacronia.","inverte conceitos")
G(1,"excecao_omitida",3,"O signo é imutável para o indivíduo, que não pode alterá-lo por decisão própria, mas é mutável historicamente, pois se transforma com o tempo.","O signo é mutável para o indivíduo, que pode alterá-lo livremente por decisão própria, e imutável historicamente, pois não se transforma com o tempo.","Mutabilidade e imutabilidade.","inverte mutabilidade")
G(1,"confusao_instituto",3,"Referente é o objeto, ser ou fato do mundo a que o signo remete, e não se confunde com o significado, que é o conceito associado ao significante.","Referente é o conceito associado ao significante no interior do signo, e não se confunde com o objeto do mundo a que o signo remete.","Referente.","confunde referente e significado")
G(1,"confusao_instituto",4,"No triângulo de Ogden e Richards, os vértices correspondem ao símbolo (a palavra), ao pensamento ou referência (o conceito) e ao referente (a coisa).","No triângulo de Ogden e Richards, os vértices correspondem ao emissor, ao receptor e à mensagem, que formam o esquema da comunicação.","Ogden e Richards.","confunde com esquema comunicativo")
G(1,"confusao_instituto",4,"Para Frege, 'estrela da manhã' e 'estrela da tarde' têm sentidos diferentes e a mesma referência, pois designam o mesmo astro.","Para Frege, 'estrela da manhã' e 'estrela da tarde' têm o mesmo sentido e referências diferentes, pois designam astros distintos.","Frege, sentido e referência.","inverte sentido e referência")
G(1,"confusao_instituto",2,"A denotação é o sentido básico, objetivo e dicionarizado de uma palavra, ao passo que a conotação é o sentido figurado, associativo, que acrescenta valores subjetivos ou culturais.","A denotação é o sentido figurado e associativo de uma palavra, ao passo que a conotação é o sentido básico, objetivo e dicionarizado.","Denotação e conotação.","inverte conceitos")
G(1,"caso_concreto",3,"Em 'O ministro tem sangue frio', a expressão 'sangue frio' é usada com sentido conotativo, pois não se refere à temperatura do sangue, e sim à serenidade diante de situações difíceis.","Em 'O ministro tem sangue frio', a expressão 'sangue frio' é usada com sentido denotativo, pois se refere, de modo literal, à temperatura do sangue do ministro.","Conotação.","classifica sentido figurado como denotativo")
G(1,"excecao_omitida",3,"A conotação é típica da linguagem literária e publicitária, mas também está presente na fala cotidiana.","A conotação é exclusiva da linguagem literária, não ocorrendo na fala cotidiana nem na linguagem publicitária.","Conotação.","restringe conotação")
G(1,"confusao_instituto",3,"A linguagem, em sentido saussuriano, é a faculdade humana de comunicar-se por signos, de caráter heterogêneo, ao passo que a língua é seu aspecto social e sistemático.","A linguagem, em sentido saussuriano, é um sistema social e homogêneo, e coincide em tudo com a língua, sem caráter heterogêneo.","Linguagem, língua e fala.","identifica linguagem e língua")
G(1,"excecao_omitida",4,"Saussure elegeu a língua, e não a fala, como objeto da linguística, por considerá-la um sistema homogêneo e passível de estudo sistemático.","Saussure elegeu a fala, e não a língua, como objeto da linguística, por considerá-la um sistema homogêneo e passível de estudo sistemático.","Objeto da linguística.","inverte objeto")
G(1,"caso_concreto",4,"Quando um falante pronuncia com sotaque próprio uma palavra do português, a pronúncia individual pertence à fala, ao passo que o sistema de sons e regras compartilhado pela comunidade pertence à língua.","Quando um falante pronuncia com sotaque próprio uma palavra do português, a pronúncia individual pertence à língua, ao passo que o sistema de sons compartilhado pela comunidade pertence à fala.","Língua e fala.","inverte exemplo")
G(1,"excecao_omitida",3,"As onomatopeias têm motivação limitada, pois a imitação do som é convencionalizada, e por isso uma mesma ação sonora recebe formas distintas em línguas diferentes.","As onomatopeias constituem prova de que o signo é sempre motivado, pois reproduzem o som de modo idêntico em todas as línguas.","Onomatopeia.","afirma motivação plena")
# ---- 2 categorias semânticas
G(2,"excecao_omitida",2,"Em português, o gênero gramatical é, em geral, arbitrário e só se relaciona com o sexo biológico em seres animados, como em 'o menino' e 'a menina'.","Em português, o gênero gramatical corresponde sempre ao sexo biológico do ser designado, inclusive em substantivos como 'mesa' e 'livro'.","Gênero.","afirma correspondência universal com o sexo")
G(2,"confusao_instituto",3,"São substantivos sobrecomuns, com um só gênero gramatical para ambos os sexos, 'testemunha' e 'criança', ao passo que 'colega' e 'jovem' são comuns de dois gêneros, distinguidos pelo determinante.","São substantivos comuns de dois gêneros 'testemunha' e 'criança', distinguidos pelo determinante, ao passo que 'colega' e 'jovem' são sobrecomuns, com um só gênero para ambos os sexos.","Gênero dos substantivos.","inverte sobrecomuns e comuns de dois gêneros")
G(2,"excecao_omitida",3,"A pessoa é categoria dêitica, pois a identificação de quem fala, de com quem se fala e de de quem se fala depende da situação de enunciação.","A pessoa é categoria independente da situação de enunciação, pois o significado de 'eu' e 'tu' é fixo e idêntico em todos os contextos.","Pessoa.","nega dêixis")
G(2,"excecao_omitida",3,"O número plural pode ter sentido diferente da simples multiplicação, como em 'férias' e 'óculos', e há substantivos usados somente no plural, como 'núpcias'.","O número plural indica, em todos os casos, a mera multiplicação do referente, e não existem substantivos usados somente no plural.","Número.","nega pluralia tantum")
G(2,"confusao_instituto",3,"A categoria de tempo localiza o evento em relação ao momento da fala ou a outro momento de referência, ao passo que o aspecto diz respeito ao modo como a ação se desenvolve.","A categoria de tempo diz respeito ao modo como a ação se desenvolve, ao passo que o aspecto localiza o evento em relação ao momento da fala.","Tempo e aspecto.","inverte tempo e aspecto")
G(2,"confusao_instituto",3,"O modo verbal expressa a atitude do falante diante do enunciado: o indicativo associa-se à certeza, o subjuntivo à dúvida ou hipótese, e o imperativo à ordem, ao pedido ou ao conselho.","O modo verbal localiza a ação no tempo: o indicativo expressa passado, o subjuntivo presente e o imperativo futuro.","Modo.","confunde modo com tempo")
G(2,"caso_concreto",4,"A diferença entre 'ela cantou' e 'ela cantava' é aspectual: o pretérito perfeito apresenta a ação como concluída e vista como um todo, e o imperfeito, como ação em curso, repetida ou habitual, no passado.","A diferença entre 'ela cantou' e 'ela cantava' é apenas de pessoa gramatical, pois ambos os verbos apresentam a ação com o mesmo aspecto.","Aspecto.","nega distinção aspectual")
G(2,"excecao_omitida",4,"Aspectos como o incoativo (início da ação), o durativo, o iterativo (repetição) e o terminativo (fim) descrevem fases ou modos de realização do evento, não sua localização temporal.","Aspectos como o incoativo, o durativo, o iterativo e o terminativo localizam o evento em relação ao momento da fala e substituem a categoria de tempo.","Tipos de aspecto.","confunde aspecto com tempo")
G(2,"confusao_instituto",3,"Papéis semânticos são relações desempenhadas pelos participantes em relação ao verbo, como agente, paciente, experienciador, beneficiário e instrumento.","Papéis semânticos são as funções sintáticas exercidas pelos termos da oração, como sujeito, objeto direto e adjunto adverbial.","Papéis semânticos.","confunde com funções sintáticas")
G(2,"caso_concreto",4,"Em 'O projeto foi entregue pelo deputado', o deputado é o agente e o projeto, o paciente (ou tema), embora o projeto ocupe a posição de sujeito sintático.","Em 'O projeto foi entregue pelo deputado', o projeto é o agente, por ocupar a posição de sujeito sintático, e o deputado é o paciente.","Papéis e voz passiva.","atribui papel pelo sujeito sintático")
G(2,"caso_concreto",4,"Em 'Maria sentiu medo', Maria desempenha o papel de experienciador, pois percebe ou vivencia um estado, e não pratica ação voluntária.","Em 'Maria sentiu medo', Maria desempenha o papel de agente, pois pratica voluntariamente a ação de sentir.","Experienciador.","classifica experienciador como agente")
G(2,"excecao_omitida",3,"O sujeito sintático nem sempre coincide com o agente da ação, o que se vê nas construções passivas.","O sujeito sintático coincide sempre com o agente da ação, inclusive nas construções passivas.","Sujeito e agente.","afirma coincidência universal")
# ---- 3 leitura
G(3,"confusao_instituto",2,"Coesão é a ligação entre elementos da superfície textual por meios linguísticos, ao passo que coerência é a continuidade de sentido, que depende também do conhecimento de mundo e da situação.","Coerência é a ligação entre elementos da superfície textual por meios linguísticos, ao passo que coesão é a continuidade de sentido, que depende do conhecimento de mundo.","Coesão e coerência.","inverte coesão e coerência")
G(3,"excecao_omitida",3,"Um texto pode ser coeso e incoerente, assim como pode ser coerente com poucos recursos coesivos explícitos.","A presença de recursos coesivos garante, necessariamente, a coerência do texto, e a coerência exige sempre elementos coesivos explícitos.","Coesão sem coerência.","afirma relação necessária")
G(3,"confusao_instituto",2,"Na referência anafórica, o termo retoma algo já dito; na catafórica, antecipa o que será dito; na exofórica, remete a elemento da situação, fora do texto.","Na referência anafórica, o termo antecipa o que será dito; na catafórica, retoma algo já dito; na exofórica, remete a elemento do próprio texto.","Anáfora, catáfora, exófora.","inverte anáfora e catáfora")
G(3,"caso_concreto",3,"Em 'Só quero dizer isto: a votação será adiada', o pronome 'isto' tem função catafórica, pois antecipa a informação que se segue.","Em 'Só quero dizer isto: a votação será adiada', o pronome 'isto' tem função anafórica, pois retoma informação já expressa antes.","Catáfora.","classifica catáfora como anáfora")
G(3,"caso_concreto",3,"Em 'Os deputados votaram o projeto. Eles aprovaram a urgência', o pronome 'eles' retoma 'os deputados' e constitui coesão referencial por anáfora.","Em 'Os deputados votaram o projeto. Eles aprovaram a urgência', o pronome 'eles' antecipa 'os deputados' e constitui coesão por catáfora.","Anáfora.","classifica anáfora como catáfora")
G(3,"excecao_omitida",3,"A elipse é a omissão de um termo recuperável pelo contexto e é recurso de coesão, como em 'Fui ao plenário e votei' (o sujeito 'eu' fica omitido).","A elipse é a repetição de um termo para reforçar a ideia e não constitui recurso de coesão.","Elipse.","confunde elipse com repetição")
G(3,"excecao_omitida",3,"A substituição de um termo por sinônimo, hiperônimo ou pronome é recurso de coesão referencial, que evita repetições desnecessárias.","A substituição de um termo por sinônimo, hiperônimo ou pronome rompe a coesão, pois impede a retomada do referente.","Substituição.","nega função coesiva")
G(3,"excecao_omitida",3,"A repetição de palavras ou de estruturas pode ser recurso coesivo, e em textos jurídicos e oficiais é frequente para garantir precisão.","A repetição de palavras jamais pode constituir recurso coesivo, e é sempre considerada defeito do texto.","Repetição.","nega valor coesivo")
G(3,"confusao_instituto",2,"A compreensão literal é a leitura do que está explícito, a interpretativa depreende o implícito e o propósito do autor, e a crítica avalia e seleciona inferências, distinguindo fato e opinião.","A compreensão literal é a leitura do que está implícito, a interpretativa limita-se ao que está explícito, e a crítica dispensa qualquer avaliação do texto.","Níveis de leitura.","embaralha níveis de leitura")
G(3,"confusao_instituto",3,"A ideia principal costuma ser expressa no tópico frasal do parágrafo, e os detalhes de apoio, como exemplos e dados, sustentam essa ideia.","Os detalhes de apoio, como exemplos e dados, constituem a ideia principal do parágrafo, e o tópico frasal é mero detalhe secundário.","Ideia principal.","inverte ideia principal e detalhes")
G(3,"confusao_instituto",3,"Conjunções como 'porém', 'contudo', 'todavia' e 'no entanto' expressam contraste, ao passo que 'pois', 'visto que' e 'porque' expressam relações de causa ou explicação.","Conjunções como 'porém', 'contudo', 'todavia' e 'no entanto' expressam causa, ao passo que 'pois', 'visto que' e 'porque' expressam contraste.","Relações lógicas.","inverte contraste e causa")
G(3,"caso_concreto",4,"Em 'Embora tenha trabalhado muito, não foi promovido', a conjunção 'embora' introduz uma concessão: o fato apresentado não impede a conclusão que se segue.","Em 'Embora tenha trabalhado muito, não foi promovido', a conjunção 'embora' introduz uma causa: o trabalho excessivo explica a ausência de promoção.","Concessão.","confunde concessão com causa")
G(3,"confusao_instituto",3,"Pressuposto é a ideia inegável, marcada na língua, como em 'Pedro parou de fumar', que pressupõe que Pedro fumava; subentendido é a sugestão dependente do contexto, que o falante pode negar.","Subentendido é a ideia inegável, marcada na língua, como em 'Pedro parou de fumar'; pressuposto é a sugestão dependente do contexto, que o falante pode negar.","Pressuposto e subentendido (Ducrot).","inverte conceitos")
G(3,"caso_concreto",4,"Quem diz 'Está frio aqui' pode sugerir que a janela seja fechada, e, se questionado, pode negar essa intenção; trata-se de subentendido, e não de pressuposto.","Quem diz 'Está frio aqui' pressupõe, de modo inegável e marcado na língua, que a janela seja fechada; trata-se de pressuposto, e não de subentendido.","Subentendido.","classifica subentendido como pressuposto")
G(3,"caso_concreto",4,"A frase 'A reforma voltou a ser discutida' pressupõe que a reforma já havia sido discutida antes, pois o verbo 'voltar' é marcador de pressuposto.","A frase 'A reforma voltou a ser discutida' apenas sugere, como subentendido negável, que a reforma já havia sido discutida antes.","Pressuposto.","trata pressuposto como subentendido")
G(3,"excecao_omitida",3,"Fato é aquilo que se pode verificar, como um dado, uma data ou uma ocorrência, ao passo que opinião é uma avaliação ou juízo.","A opinião atribuída a uma autoridade passa a ser fato do texto, pois a autoridade a sustenta.","Fato e opinião.","transforma opinião atribuída em fato")
G(3,"caso_concreto",3,"Em 'Infelizmente, a sessão foi encerrada', o advérbio 'infelizmente' marca opinião do enunciador, ao passo que 'a sessão foi encerrada' é fato verificável.","Em 'Infelizmente, a sessão foi encerrada', todo o enunciado é fato verificável, pois o advérbio 'infelizmente' não acrescenta avaliação.","Marcas de opinião.","ignora marca de opinião")
G(3,"confusao_instituto",3,"A derivação parassintética forma palavras pelo acréscimo simultâneo de prefixo e sufixo, como em 'entardecer'; a derivação regressiva forma substantivos por redução de verbos, como em 'ataque' (de atacar).","A derivação parassintética forma palavras pela redução de verbos, como em 'ataque'; a regressiva forma palavras pelo acréscimo simultâneo de prefixo e sufixo, como em 'entardecer'.","Formação de palavras.","inverte derivações")
G(3,"confusao_instituto",3,"Na composição por justaposição, os elementos mantêm sua integridade (guarda-chuva); na aglutinação, há perda de elementos ou de sons (planalto, de plano e alto).","Na composição por aglutinação, os elementos mantêm sua integridade (guarda-chuva); na justaposição, há perda de sons de um dos elementos (planalto).","Composição.","inverte justaposição e aglutinação")
G(3,"confusao_instituto",3,"Ditongo é o encontro de vogal e semivogal na mesma sílaba, ao passo que hiato é o encontro de duas vogais em sílabas separadas, como em 'saída'.","Hiato é o encontro de vogal e semivogal na mesma sílaba, ao passo que ditongo é o encontro de duas vogais em sílabas separadas, como em 'saída'.","Grupos vocálicos.","inverte ditongo e hiato")
G(3,"confusao_instituto",3,"São parônimas palavras semelhantes na forma e diferentes no sentido, como 'cumprimento' e 'comprimento', 'infligir' e 'infringir'; são homônimas as que têm mesma pronúncia ou grafia e sentidos diferentes.","São homônimas palavras semelhantes na forma e diferentes no sentido, como 'cumprimento' e 'comprimento'; são parônimas as que têm exatamente a mesma pronúncia e grafia.","Homônimos e parônimos.","inverte homônimas e parônimas")
G(3,"excecao_omitida",3,"Palavras cognatas partilham o mesmo radical, como 'terra', 'terreno' e 'enterrar'.","Palavras cognatas são as que têm sentidos opostos, como 'terra' e 'mar'.","Cognatas.","confunde cognatas com antônimas")
G(3,"confusao_instituto",3,"Hiperonímia é a relação entre um termo mais geral e outro mais específico, como 'flor' em relação a 'rosa'; a hiponímia é a relação inversa, do termo mais específico com o geral.","Hiponímia é a relação entre um termo mais geral e outro mais específico, como 'flor' em relação a 'rosa'; a hiperonímia é a relação inversa.","Hiperonímia e hiponímia.","inverte hiperonímia e hiponímia")
G(3,"excecao_omitida",3,"Campo semântico é o conjunto de palavras associadas a uma mesma área de significado, como 'juiz', 'sentença' e 'réu' no campo da justiça.","Campo semântico é o conjunto de palavras que têm o mesmo radical, como 'terra', 'terreno' e 'enterrar'.","Campo semântico.","confunde com família de palavras")
G(3,"excecao_omitida",3,"A sinonímia raramente é perfeita, pois palavras sinônimas costumam diferir em registro, conotação ou contexto de uso.","A sinonímia é sempre perfeita, e as palavras sinônimas são intercambiáveis em qualquer contexto, sem diferença de registro ou sentido.","Sinonímia.","afirma sinonímia perfeita")
G(3,"confusao_instituto",3,"Na organização retórica do parágrafo, a definição explica o que algo é, a exemplificação ilustra a ideia com casos, a especificação detalha o geral e a descrição caracteriza ou apresenta atributos.","Na organização retórica do parágrafo, a exemplificação explica o que algo é, a definição ilustra a ideia com casos, e a generalização detalha o específico.","Organização retórica.","embaralha recursos retóricos")
G(3,"excecao_omitida",3,"A generalização apresenta uma afirmação ampla, de que as demais ideias do parágrafo costumam decorrer ou que os exemplos ilustram.","A generalização é o recurso pelo qual o autor apresenta apenas casos particulares, sem qualquer afirmação ampla.","Generalização.","inverte conceito")
G(3,"excecao_omitida",3,"A compreensão crítica envolve a seleção de inferências cabíveis a partir do texto, e não de qualquer conclusão que o leitor queira atribuir ao autor.","A compreensão crítica permite ao leitor atribuir ao autor qualquer conclusão, ainda que sem apoio no texto.","Inferência.","nega apoio no texto")
G(3,"excecao_omitida",3,"A conexão é recurso coesivo realizado por conjunções e locuções que ligam orações, períodos e parágrafos.","A conexão é recurso coesivo realizado exclusivamente por pronomes, e não por conjunções ou locuções.","Conexão.","restringe conexão a pronomes")
G(3,"excecao_omitida",3,"O propósito do autor é elemento da compreensão interpretativa, e sua identificação depende de pistas do texto, como escolha lexical e organização argumentativa.","O propósito do autor está sempre explícito no texto, de modo que a compreensão interpretativa dispensa qualquer inferência.","Propósito do autor.","nega inferência")
G(3,"excecao_omitida",3,"A repetição pode ser usada com valor enfático, mas, em texto oficial, deve ser evitada quando for mera redundância.","A repetição é sempre vedada em qualquer gênero textual, ainda que tenha valor enfático.","Repetição.","veda repetição")
G(3,"caso_concreto",4,"Em um parágrafo que começa afirmando que 'a transparência fortalece a democracia' e a seguir cita o caso das sessões transmitidas ao vivo, o caso citado é recurso de exemplificação a serviço da ideia principal.","Em um parágrafo que começa afirmando que 'a transparência fortalece a democracia' e a seguir cita o caso das sessões transmitidas ao vivo, o caso citado é a ideia principal e a frase inicial é mero detalhe.","Exemplificação.","inverte principal e apoio")
# ---- 4 recursos
G(4,"excecao_omitida",2,"No texto oficial, os recursos estilísticos são contidos, em favor da impessoalidade, da clareza e da concisão.","No texto oficial, os recursos estilísticos devem ser ostensivos, em favor da expressividade pessoal do redator.","Texto oficial.","inverte contenção")
G(4,"confusao_instituto",3,"Entre os recursos estruturais de um texto estão a organização em introdução, desenvolvimento e conclusão, o parágrafo com tópico frasal e a progressão temática; entre os estilísticos, as figuras de linguagem e a escolha lexical.","Entre os recursos estruturais de um texto estão as figuras de linguagem e a escolha lexical; entre os estilísticos, a organização em introdução, desenvolvimento e conclusão.","Recursos estruturais e estilísticos.","troca categorias")
G(4,"excecao_omitida",3,"Adequar a linguagem ao gênero não é o mesmo que corrigi-la: uma frase pode ser gramaticalmente correta e inadequada à situação de comunicação.","Adequar a linguagem ao gênero é o mesmo que corrigi-la, pois toda frase gramaticalmente correta é adequada a qualquer situação.","Adequação.","iguala adequação e correção")
G(4,"caso_concreto",3,"O uso de gíria em um ofício dirigido a um ministro é exemplo de inadequação ao gênero e ao interlocutor, ainda que a frase seja compreensível.","O uso de gíria em um ofício dirigido a um ministro é adequado ao gênero, desde que a frase seja compreensível.","Inadequação.","admite gíria em ofício")
G(4,"excecao_omitida",3,"A progressão temática combina a retomada de informação já conhecida (dado) com o acréscimo de informação nova.","A progressão temática consiste em repetir a mesma informação, sem acréscimo de informação nova.","Progressão temática.","nega informação nova")
G(4,"excecao_omitida",3,"Cada gênero reclama recursos próprios: o jurídico e o oficial exigem precisão e objetividade, ao passo que o literário admite a polissemia.","Os mesmos recursos estilísticos servem a qualquer gênero, e o texto jurídico deve, tanto quanto o literário, explorar a polissemia.","Recursos por gênero.","nega especificidade por gênero")
G(4,"excecao_omitida",3,"As convenções da escrita abrangem ortografia, pontuação, paragrafação e formatação, além das normas específicas do gênero.","As convenções da escrita limitam-se à ortografia, sendo irrelevantes a pontuação, a paragrafação e as normas do gênero.","Convenções da escrita.","restringe convenções")
G(4,"excecao_omitida",3,"O parágrafo bem estruturado costuma ter tópico frasal, desenvolvimento e fecho.","O parágrafo bem estruturado dispensa tópico frasal e deve conter apenas o desenvolvimento, sem fecho.","Parágrafo.","omite estrutura")
G(4,"caso_concreto",4,"Um redator que, em um relatório técnico, usa linguagem direta, frases curtas e vocabulário preciso está adotando recursos adequados ao gênero.","Um redator que, em um relatório técnico, usa linguagem rebuscada, frases longas e figuras de linguagem está adotando recursos adequados ao gênero.","Recursos do relatório.","inverte adequação")
G(4,"excecao_omitida",3,"Títulos e subtítulos são recursos estruturais que organizam a leitura e indicam a progressão do texto.","Títulos e subtítulos são recursos estilísticos sem função na organização da leitura.","Títulos e subtítulos.","nega função estrutural")
G(4,"excecao_omitida",3,"A inversão da ordem e a pontuação expressiva são recursos estilísticos que, no texto oficial, devem ser evitados em favor da ordem direta.","A inversão da ordem e a pontuação expressiva são recursos estruturais de uso obrigatório no texto oficial.","Inversão e pontuação expressiva.","troca natureza e obrigatoriedade")
# ---- 5 enunciação
G(5,"confusao_instituto",2,"Enunciação é o ato de dizer, e enunciado é o produto desse ato, aquilo que foi dito.","Enunciação é o produto do ato de dizer, aquilo que foi dito, e enunciado é o ato de dizer.","Benveniste.","inverte enunciação e enunciado")
G(5,"excecao_omitida",3,"Os dêiticos de pessoa, tempo e espaço, como 'eu', 'agora' e 'aqui', só se interpretam em relação à situação de enunciação.","Os dêiticos de pessoa, tempo e espaço, como 'eu', 'agora' e 'aqui', têm sentido fixo e independente da situação de enunciação.","Dêixis.","nega dependência da situação")
G(5,"caso_concreto",3,"Em um discurso lido em plenário, a expressão 'hoje' remete ao dia da leitura, o que mostra a dependência dos dêiticos em relação ao momento da enunciação.","Em um discurso lido em plenário, a expressão 'hoje' remete sempre à data de publicação do texto, independentemente do momento da leitura.","Dêiticos temporais.","fixa dêitico em momento diverso")
G(5,"confusao_instituto",2,"Texto é a unidade de sentido materializada, ao passo que discurso é o texto em sua dimensão social e histórica, ligado às condições de produção e a outros discursos.","Discurso é a unidade de sentido materializada, sem relação com condições de produção, ao passo que texto é o produto social e histórico ligado a outros discursos.","Texto e discurso.","inverte texto e discurso")
G(5,"excecao_omitida",4,"Para a análise do discurso de linha francesa, o sentido não é transparente: depende da formação discursiva e ideológica em que o enunciado é produzido.","Para a análise do discurso de linha francesa, o sentido é transparente e independente da formação discursiva, pois decorre da intenção consciente do emissor.","Pêcheux.","nega condições de produção")
G(5,"confusao_instituto",3,"O interdiscurso é o conjunto de discursos anteriores e externos que sustentam o que se diz em um enunciado, e é constitutivo de todo discurso.","O interdiscurso é o discurso que o próprio emissor produz no interior de um único texto, sem relação com outros discursos.","Interdiscurso.","redefine interdiscurso")
G(5,"confusao_instituto",3,"Para Bakhtin, o dialogismo é constitutivo da linguagem: todo enunciado responde a enunciados anteriores e antecipa respostas.","Para Bakhtin, o dialogismo ocorre apenas em textos que reproduzem diálogos entre personagens, e não é constitutivo da linguagem.","Dialogismo.","restringe dialogismo a diálogos")
G(5,"excecao_omitida",3,"A polifonia, na obra de Bakhtin sobre Dostoiévski, refere-se à presença de várias vozes autônomas no texto, que não se submetem à voz do autor.","A polifonia, na obra de Bakhtin sobre Dostoiévski, refere-se à presença de uma única voz, a do autor, que organiza todas as demais.","Polifonia.","inverte polifonia")
G(5,"excecao_omitida",4,"Ducrot, ao retomar a noção de polifonia na linguística, distingue o locutor e os enunciadores, e admite que o autor empírico não se identifica sempre com a voz que se manifesta no enunciado.","Ducrot, ao retomar a noção de polifonia na linguística, afirma que o locutor e o autor empírico são sempre a mesma instância, não havendo enunciadores distintos.","Ducrot, polifonia.","identifica locutor e autor")
G(5,"excecao_omitida",3,"As esferas sociais de comunicação, como a jurídica, a jornalística e a política, determinam os gêneros do discurso que nelas circulam.","As esferas sociais de comunicação não influenciam os gêneros do discurso, que são idênticos em todas as esferas.","Esferas sociais.","nega influência")
G(5,"confusao_instituto",3,"Na retórica clássica, ethos refere-se à credibilidade do orador, pathos à emoção despertada no auditório e logos ao argumento racional.","Na retórica clássica, ethos refere-se ao argumento racional, pathos à credibilidade do orador e logos à emoção despertada no auditório.","Aristóteles, provas.","embaralha provas")
G(5,"confusao_instituto",3,"No gênero deliberativo, o orador trata do futuro e do que é útil ou nocivo; no judiciário, do passado e do justo e do injusto; no epidítico, do presente, em louvor ou censura.","No gênero deliberativo, o orador trata do passado e do justo e do injusto; no judiciário, do futuro e do útil; no epidítico, do futuro, em louvor.","Gêneros retóricos.","embaralha gêneros retóricos")
G(5,"caso_concreto",4,"Um discurso de homenagem a um parlamentar falecido, proferido em plenário, tem natureza epidítica, por visar ao louvor no presente.","Um discurso de homenagem a um parlamentar falecido, proferido em plenário, tem natureza judiciária, por visar a julgar fatos passados.","Discurso epidítico.","classifica gênero retórico errado")
G(5,"caso_concreto",4,"O discurso de um deputado que defende a aprovação de um projeto, a fim de convencer seus pares sobre o que é útil ao país, é, em essência, de natureza deliberativa.","O discurso de um deputado que defende a aprovação de um projeto, a fim de convencer seus pares sobre o que é útil ao país, é, em essência, de natureza epidítica.","Discurso parlamentar.","classifica gênero retórico errado")
G(5,"excecao_omitida",3,"A situação de comunicação inclui emissor, receptor, canal, código, mensagem, contexto e finalidade, além das circunstâncias de produção.","A situação de comunicação inclui apenas o emissor e o receptor, sendo irrelevantes o canal, o código e o contexto.","Situação de comunicação.","reduz elementos")
G(5,"excecao_omitida",3,"As cinco partes da produção do discurso na retórica clássica são inventio, dispositio, elocutio, memoria e actio.","As cinco partes da produção do discurso na retórica clássica são ethos, pathos, logos, exórdio e peroração.","Partes da retórica.","confunde produção e partes do discurso")
G(5,"excecao_omitida",3,"Na oratória parlamentar, o aparte e a questão de ordem são formas regimentais de uso da palavra, que se submetem a regras de procedimento.","Na oratória parlamentar, o aparte e a questão de ordem são livres e independentes de qualquer regra regimental.","Oratória parlamentar.","nega regras regimentais")
# ---- 6 gêneros e tipologia
G(6,"confusao_instituto",2,"Para Bakhtin, gêneros do discurso são tipos relativamente estáveis de enunciados, caracterizados por conteúdo temático, construção composicional e estilo.","Para Bakhtin, gêneros do discurso são categorias fixas e imutáveis de enunciados, em número limitado, definidas apenas pela estrutura gramatical.","Bakhtin.","atribui fixidez e número limitado")
G(6,"confusao_instituto",3,"Tipos textuais, em número limitado, são sequências definidas por aspectos linguísticos internos, como narração, descrição, exposição, argumentação e injunção; gêneros textuais são inúmeros e históricos.","Gêneros textuais, em número limitado, são sequências como narração e descrição; tipos textuais são inúmeros e históricos, como carta, notícia e ofício.","Marcuschi.","inverte tipo e gênero")
G(6,"caso_concreto",3,"Carta, notícia e ofício são gêneros textuais, ao passo que narração, descrição e injunção são tipos textuais.","Carta, notícia e ofício são tipos textuais, ao passo que narração, descrição e injunção são gêneros textuais.","Gêneros e tipos.","troca gêneros e tipos")
G(6,"excecao_omitida",3,"Um mesmo gênero pode combinar mais de um tipo textual, como uma carta que narra, descreve e argumenta, definindo-se o tipo dominante pela sequência predominante.","Um mesmo gênero só pode apresentar um único tipo textual, de modo que uma carta nunca pode combinar narração e argumentação.","Heterogeneidade tipológica.","nega combinação de tipos")
G(6,"confusao_instituto",3,"A macroestrutura de um texto refere-se à sua organização global, e a microestrutura à organização local, como frases, conectores e escolhas lexicais e sintáticas.","A macroestrutura de um texto refere-se à organização local, como frases e conectores, e a microestrutura à organização global.","Macro e microestrutura.","inverte macro e microestrutura")
G(6,"caso_concreto",4,"O parecer jurídico, que expõe fundamentos e conclui por uma recomendação, é um gênero em que predominam sequências expositivas e argumentativas.","O parecer jurídico é um tipo textual narrativo, em que predominam sequências de ação no tempo.","Parecer.","classifica gênero como tipo narrativo")
G(6,"confusao_instituto",3,"A intertextualidade é a relação de um texto com outros textos, e pode ser explícita, como na citação e na epígrafe, ou implícita, como na alusão e na paródia.","A intertextualidade é a relação entre as partes de um mesmo texto, e ocorre apenas quando há citação com indicação de fonte.","Intertextualidade.","reduz a citação explícita")
G(6,"confusao_instituto",3,"A paráfrase reformula um texto mantendo o sentido, ao passo que a paródia subverte o texto original, em geral com humor ou crítica.","A paráfrase subverte o texto original com humor ou crítica, ao passo que a paródia reformula o texto mantendo o sentido.","Paráfrase e paródia.","inverte paráfrase e paródia")
G(6,"excecao_omitida",4,"O termo intertextualidade foi cunhado por Kristeva a partir das ideias de Bakhtin sobre o dialogismo.","O termo intertextualidade foi cunhado por Saussure, a partir de suas ideias sobre a arbitrariedade do signo.","Kristeva.","atribui a Saussure")
G(6,"confusao_instituto",3,"A retextualização é a transformação de um texto em outro, por mudança de gênero, de modalidade ou de finalidade, e envolve compreensão e reelaboração, não simples transcrição.","A retextualização é a simples transcrição de um texto falado, com reprodução literal de todas as marcas de oralidade, sem reelaboração.","Marcuschi, retextualização.","reduz a transcrição literal")
G(6,"caso_concreto",4,"Transformar a gravação de uma audiência pública em uma ata escrita é exemplo de retextualização, que exige eliminar marcas de oralidade, reorganizar a sintaxe e pontuar.","Transformar a gravação de uma audiência pública em uma ata escrita é mera transcrição, que dispensa qualquer reorganização da sintaxe ou eliminação de marcas de oralidade.","Fala para escrita.","trata retextualização como transcrição")
G(6,"excecao_omitida",3,"A citação é a reprodução literal de um trecho, com marcação e indicação de fonte, e é forma explícita de intertextualidade.","A citação é a reformulação livre de um trecho, sem marcação, e constitui forma implícita de intertextualidade.","Citação.","confunde citação com paráfrase")
G(6,"excecao_omitida",3,"A reescritura é a reelaboração de um texto próprio ou alheio, que pode preservar ou reorientar o sentido.","A reescritura é sempre a cópia literal de um texto, sem alteração de qualquer natureza.","Reescritura.","reduz a cópia literal")
G(6,"confusao_instituto",3,"A epígrafe é recurso de intertextualidade explícita, pois consiste em citação posta no início do texto com indicação de autoria.","A epígrafe é recurso de intertextualidade implícita, pois consiste em alusão sem indicação de autoria.","Epígrafe.","troca explícita e implícita")
G(6,"excecao_omitida",3,"O gênero do discurso é histórico e social, e novos gêneros surgem com novas esferas e tecnologias de comunicação, como o e-mail e a mensagem instantânea.","O gênero do discurso é atemporal e natural, e novos gêneros não surgem com o desenvolvimento de novas tecnologias de comunicação.","Gêneros e história.","nega historicidade")
G(6,"caso_concreto",4,"Em uma sequência injuntiva, como a de uma receita ou de uma instrução normativa, predomina o modo imperativo ou formas equivalentes de comando.","Em uma sequência injuntiva, como a de uma receita ou instrução, predomina a descrição de atributos de seres, sem formas de comando.","Tipo injuntivo.","confunde injunção com descrição")
G(6,"excecao_omitida",3,"A construção composicional diz respeito à organização e ao acabamento do todo do enunciado, e é um dos elementos que caracterizam o gênero.","A construção composicional diz respeito apenas à ortografia das palavras, e não é elemento que caracterize o gênero.","Construção composicional.","reduz a ortografia")
# ---- 7 variação
G(7,"confusao_instituto",2,"Dialeto é a variedade ligada ao grupo de falantes, por região ou classe, e registro é a variedade ligada à situação de uso, como o grau de formalidade.","Registro é a variedade ligada ao grupo de falantes, por região ou classe, e dialeto é a variedade ligada à situação de uso.","Dialeto e registro.","inverte dialeto e registro")
G(7,"excecao_omitida",3,"Um mesmo falante pode dominar vários registros e escolher entre eles conforme a situação de comunicação.","Cada falante domina um único registro, que utiliza em todas as situações de comunicação.","Registros.","nega pluralidade de registros")
G(7,"caso_concreto",3,"O uso de 'mandioca', 'macaxeira' e 'aipim' para designar a mesma raiz é exemplo de variação diatópica, ligada ao lugar.","O uso de 'mandioca', 'macaxeira' e 'aipim' para designar a mesma raiz é exemplo de variação diacrônica, ligada ao tempo.","Variação diatópica.","classifica regional como diacrônica")
G(7,"caso_concreto",3,"A alternância entre 'Venho solicitar' e 'Tô pedindo' exemplifica a variação diafásica, ligada à situação de comunicação e ao grau de formalidade.","A alternância entre 'Venho solicitar' e 'Tô pedindo' exemplifica a variação diatópica, ligada ao lugar de origem do falante.","Variação diafásica.","classifica diafásica como diatópica")
G(7,"confusao_instituto",3,"A variação diastrática relaciona-se ao grupo social do falante, como escolaridade, classe e idade, ao passo que a diacrônica se relaciona ao tempo.","A variação diastrática relaciona-se ao tempo, e a diacrônica ao grupo social do falante, como escolaridade, classe e idade.","Variação diastrática e diacrônica.","inverte diastrática e diacrônica")
G(7,"caso_concreto",3,"A passagem de 'vosmecê' para 'você' ao longo da história é exemplo de variação diacrônica.","A passagem de 'vosmecê' para 'você' ao longo da história é exemplo de variação diamésica.","Variação diacrônica.","classifica diacrônica como diamésica")
G(7,"confusao_instituto",3,"A variação diamésica relaciona-se ao meio de produção do texto, a distinção entre fala e escrita.","A variação diamésica relaciona-se à região de origem do falante, e não ao meio de produção do texto.","Variação diamésica.","troca fator de variação")
G(7,"excecao_omitida",3,"Oralidade e escrita são modalidades de uso da língua que formam um continuum de gêneros, e não uma dicotomia absoluta.","Oralidade e escrita são modalidades absolutamente opostas, de modo que toda fala é informal e toda escrita é formal.","Oralidade e escrita.","afirma dicotomia absoluta")
G(7,"caso_concreto",4,"Uma conferência é gênero falado formal, e um bilhete entre amigos é gênero escrito informal, o que mostra que formalidade não se confunde com modalidade.","Uma conferência é gênero falado informal por ser oral, e um bilhete entre amigos é gênero escrito formal por ser escrito.","Formalidade e modalidade.","confunde formalidade com modalidade")
G(7,"confusao_instituto",3,"A norma-padrão é um modelo idealizado e codificado nas gramáticas normativas, ao passo que a norma culta é a variedade efetivamente usada por falantes escolarizados em situações monitoradas.","A norma-padrão é a variedade efetivamente usada por falantes escolarizados em situações monitoradas, ao passo que a norma culta é um modelo idealizado e codificado nas gramáticas.","Norma-padrão e norma culta.","inverte norma-padrão e norma culta")
G(7,"excecao_omitida",3,"As variedades populares e regionais também são normas, com regras próprias, e não são erro.","As variedades populares e regionais não obedecem a regra alguma e constituem apenas desvios aleatórios da norma-padrão.","Normas linguísticas.","nega sistematicidade")
G(7,"excecao_omitida",3,"O preconceito linguístico consiste em julgar uma variedade como errada ou inferior por razões sociais, e não por critérios linguísticos.","O preconceito linguístico consiste em reconhecer que todas as variedades têm valor e funcionam em situações específicas.","Preconceito linguístico.","inverte conceito")
G(7,"excecao_omitida",3,"Na construção do texto escrito formal, a variação linguística deve ser considerada, e o texto exige adequação à norma culta sem que isso torne as demais variedades inferiores.","Na construção do texto escrito formal, a variação linguística é irrelevante, e a adequação à norma culta torna as demais variedades inferiores do ponto de vista linguístico.","Variação e escrita.","atribui inferioridade linguística")
G(7,"excecao_omitida",3,"Toda língua viva varia, e as variantes são formas distintas de dizer a mesma coisa, avaliadas socialmente.","Somente as línguas mortas variam, e as variantes das línguas vivas são erros que devem ser corrigidos.","Variação.","nega variação em línguas vivas")
G(7,"caso_concreto",4,"O uso de 'a gente' no lugar de 'nós' e a alternância entre 'tu' e 'você' são variações do português brasileiro que não impedem a comunicação e dependem de região e situação.","O uso de 'a gente' no lugar de 'nós' e a alternância entre 'tu' e 'você' são exemplos de erro gramatical que impedem a comunicação em qualquer situação.","Variação no português do Brasil.","trata variação como erro")
G(7,"excecao_omitida",3,"A gíria é uma variedade de grupo, ligada em geral à variação diastrática, e pode ser inadequada em contextos formais, mas é legítima em seus contextos de uso.","A gíria é sempre erro e não pode ser considerada variedade linguística em nenhum contexto.","Gíria.","nega legitimidade")
G(7,"excecao_omitida",3,"Formalidade e informalidade referem-se ao grau de monitoramento da linguagem e à situação de uso.","Formalidade e informalidade referem-se à modalidade, de modo que todo texto escrito é formal e todo texto falado é informal.","Formalidade.","confunde com modalidade")
# ---- 8 gramática
G(8,"confusao_instituto",2,"Toda gramática normativa estabelece regras do bem falar e escrever com base em um modelo ideal, ao passo que a descritiva registra o funcionamento real da língua, sem julgá-lo.","A gramática descritiva estabelece regras do bem falar e escrever com base em um modelo ideal, ao passo que a normativa registra o funcionamento real da língua.","Concepções de gramática.","inverte normativa e descritiva")
G(8,"excecao_omitida",3,"A gramática internalizada é o conjunto de regras que o falante domina intuitivamente, base de sua competência linguística, independentemente de escolarização.","A gramática internalizada é o conjunto de regras ensinadas na escola, e só se adquire com o estudo formal da norma-padrão.","Gramática internalizada.","atribui ao ensino formal")
G(8,"excecao_omitida",3,"A gramática de uso ou funcional explica as formas linguísticas pelas funções que desempenham na comunicação.","A gramática de uso ou funcional explica as formas linguísticas exclusivamente por critérios de correção segundo a norma-padrão.","Gramática funcional.","reduz à correção")
G(8,"excecao_omitida",3,"A gramática tradicional é de natureza normativa, pois prescreve usos considerados corretos.","A gramática tradicional é de natureza descritiva, pois registra todos os usos da língua, sem prescrever.","Gramática tradicional.","atribui natureza descritiva")
G(8,"confusao_instituto",3,"Correção e incorreção referem-se ao cumprimento ou descumprimento da norma-padrão; adequação e inadequação referem-se à compatibilidade da forma com a situação de comunicação.","Correção e incorreção referem-se à compatibilidade da forma com a situação de comunicação; adequação e inadequação referem-se ao cumprimento da norma-padrão.","Correção e adequação.","inverte critérios")
G(8,"caso_concreto",4,"Uma linguagem rebuscada em um recado informal entre colegas pode ser correta, segundo a norma-padrão, e inadequada à situação.","Uma linguagem rebuscada em um recado informal entre colegas é, por ser correta, necessariamente adequada à situação.","Correta e inadequada.","iguala correção e adequação")
G(8,"caso_concreto",4,"Uma construção coloquial que se afasta da norma-padrão pode ser incorreta segundo a gramática normativa e, ainda assim, adequada a um diálogo entre amigos.","Uma construção coloquial que se afasta da norma-padrão é, por isso, inadequada a qualquer situação de comunicação.","Incorreta e adequada.","nega adequação do coloquial")
G(8,"confusao_instituto",3,"Propriedade é o uso do termo exato, que traduz com precisão a ideia; impropriedade é o emprego de palavra em sentido que ela não tem ou menos preciso.","Propriedade é o emprego de palavra em sentido que ela não tem; impropriedade é o uso do termo exato que traduz com precisão a ideia.","Propriedade e impropriedade.","inverte conceitos")
G(8,"caso_concreto",3,"Empregar 'infringir' com o sentido de 'infligir', como em 'infringir uma pena', é caso de impropriedade vocabular.","Empregar 'infringir' com o sentido de 'infligir', como em 'infringir uma pena', é exemplo de propriedade vocabular.","Impropriedade.","classifica impropriedade como propriedade")
G(8,"excecao_omitida",3,"A gramática descritiva nunca é, por definição, incompatível com o ensino da norma culta, pois descrever os usos reais inclui descrever a norma culta.","A gramática descritiva é incompatível com o ensino da norma culta, pois nega a existência de qualquer norma.","Descritiva e norma culta.","afirma incompatibilidade")
G(8,"excecao_omitida",3,"Uma frase pode ser gramaticalmente correta e, mesmo assim, impertinente ou imprópria para o contexto comunicativo.","Toda frase gramaticalmente correta é, por isso, adequada e própria a qualquer contexto comunicativo.","Correção e contexto.","iguala correção e contexto")
G(8,"excecao_omitida",3,"As concepções de gramática diferem quanto ao objeto: a normativa trata do que se deve usar, a descritiva do que se usa e a internalizada do que o falante sabe.","As concepções de gramática não diferem quanto ao objeto, e todas tratam apenas do que se deve usar segundo a norma-padrão.","Objetos das gramáticas.","nega diferença de objeto")
# ---- 9 funções da linguagem
G(9,"confusao_instituto",2,"Na classificação de Jakobson, a função emotiva centra-se no emissor, a conativa no receptor, a referencial no contexto, a fática no canal, a metalinguística no código e a poética na mensagem.","Na classificação de Jakobson, a função emotiva centra-se no receptor, a conativa no emissor, a referencial no código, a fática na mensagem, a metalinguística no canal e a poética no contexto.","Jakobson (1960).","embaralha fatores")
G(9,"caso_concreto",2,"A frase 'Vote consciente!' tem função predominantemente conativa, por se voltar ao receptor e fazer uso do imperativo.","A frase 'Vote consciente!' tem função predominantemente emotiva, por se centrar no emissor e expressar seus sentimentos.","Função conativa.","classifica conativa como emotiva")
G(9,"caso_concreto",2,"A frase 'A Câmara tem 513 deputados' tem função predominantemente referencial, por se centrar no contexto e usar a terceira pessoa de forma objetiva.","A frase 'A Câmara tem 513 deputados' tem função predominantemente poética, por se centrar na forma da mensagem.","Função referencial.","classifica referencial como poética")
G(9,"caso_concreto",3,"'Alô? Está me ouvindo?', em uma ligação, tem função predominantemente fática, pois visa a testar ou manter o contato.","'Alô? Está me ouvindo?', em uma ligação, tem função predominantemente metalinguística, pois a língua explica a própria língua.","Função fática.","classifica fática como metalinguística")
G(9,"caso_concreto",3,"O verbete de um dicionário, como 'Quórum: número mínimo de presentes', exerce função metalinguística, pois a língua é usada para explicar a própria língua.","O verbete de um dicionário, como 'Quórum: número mínimo de presentes', exerce função fática, pois visa a manter o contato com o leitor.","Função metalinguística.","classifica metalinguística como fática")
G(9,"caso_concreto",3,"O verso 'Um, dois, feijão com arroz' tem função predominantemente poética, por privilegiar ritmo, rima e sonoridade.","O verso 'Um, dois, feijão com arroz' tem função predominantemente referencial, por informar fatos do mundo com objetividade.","Função poética.","classifica poética como referencial")
G(9,"caso_concreto",3,"'Que saudade eu sinto da minha cidade!' tem função predominantemente emotiva, por centrar-se no emissor, com uso da primeira pessoa e da exclamação.","'Que saudade eu sinto da minha cidade!' tem função predominantemente conativa, por centrar-se no receptor e fazer uso do imperativo.","Função emotiva.","classifica emotiva como conativa")
G(9,"excecao_omitida",3,"É comum um mesmo texto apresentar mais de uma função da linguagem, e a função predominante é a do fator em que a mensagem se centra.","Cada texto apresenta uma única função da linguagem, e nunca é possível que mais de uma função apareça no mesmo texto.","Funções combinadas.","afirma função única")
G(9,"excecao_omitida",3,"Nos textos jornalísticos e oficiais predomina, em geral, a função referencial; na publicidade, a conativa; na literatura, a poética.","Nos textos jornalísticos e oficiais predomina a função poética; na publicidade, a referencial; na literatura, a conativa.","Funções por gênero.","embaralha funções")
G(9,"excecao_omitida",3,"Na linguagem oficial predomina a função referencial, mas a conativa aparece em pedidos e ordens e a fática em saudações e fechos protocolares.","Na linguagem oficial predomina a função poética, e a fática e a conativa são sempre vedadas.","Funções no texto oficial.","afirma predominância poética")
G(9,"excecao_omitida",3,"A função referencial é também chamada denotativa e caracteriza-se, em regra, pela objetividade e pelo uso da terceira pessoa.","A função referencial é também chamada emotiva e caracteriza-se, em regra, pela subjetividade e pelo uso da primeira pessoa.","Função referencial.","troca denominação")
G(9,"caso_concreto",4,"Um poema que reflete sobre o ato de escrever poemas combina a função poética com a metalinguística.","Um poema que reflete sobre o ato de escrever poemas não pode ter função metalinguística, pois a poética a exclui.","Poesia metalinguística.","exclui função combinada")
G(9,"caso_concreto",4,"O slogan 'Compre agora e leve dois!' tem predominantemente função conativa, pois busca persuadir o receptor a agir.","O slogan 'Compre agora e leve dois!' tem predominantemente função referencial, pois informa dados do mundo sem tentar influenciar o receptor.","Slogan.","classifica conativa como referencial")
G(9,"confusao_instituto",3,"A função emotiva, também chamada expressiva, relaciona-se com as emoções e atitudes do emissor, ao passo que a conativa, também chamada apelativa, relaciona-se com a ação sobre o receptor.","A função emotiva, também chamada apelativa, relaciona-se com a ação sobre o receptor, ao passo que a conativa, também chamada expressiva, relaciona-se com as emoções do emissor.","Sinônimos das funções.","troca denominações")
G(9,"excecao_omitida",3,"As marcas típicas da função conativa são o imperativo, o vocativo e a segunda pessoa.","As marcas típicas da função conativa são a primeira pessoa, as exclamações e as interjeições.","Marcas da conativa.","atribui marcas da emotiva")
G(9,"excecao_omitida",3,"As marcas típicas da função emotiva são a primeira pessoa, as exclamações e as interjeições.","As marcas típicas da função emotiva são o imperativo, o vocativo e a segunda pessoa.","Marcas da emotiva.","atribui marcas da conativa")
# ---- 10 retórica e figuras
G(10,"confusao_instituto",2,"Na metáfora, há comparação implícita, sem conectivo; na comparação, há conectivo explícito, como 'como' ou 'tal qual'.","Na metáfora, há comparação explícita, com conectivo, como 'como' ou 'tal qual'; na comparação, a relação é implícita, sem conectivo.","Metáfora e comparação.","inverte metáfora e comparação")
G(10,"caso_concreto",2,"A frase 'Aquele político é uma raposa' contém metáfora, ao passo que 'Aquele político é esperto como uma raposa' contém comparação.","A frase 'Aquele político é uma raposa' contém comparação, ao passo que 'Aquele político é esperto como uma raposa' contém metáfora.","Metáfora e comparação.","inverte exemplos")
G(10,"confusao_instituto",3,"A metonímia consiste na substituição de um termo por outro por relação de proximidade ou contiguidade, como em 'Li Machado de Assis' (autor pela obra).","A metonímia consiste na substituição de um termo por outro por relação de semelhança, como em 'Aquele político é uma raposa'.","Metonímia.","confunde metonímia com metáfora")
G(10,"caso_concreto",3,"Em 'Bebi um copo de água', há metonímia, pois se toma o continente (copo) pelo conteúdo (a água).","Em 'Bebi um copo de água', há metáfora, pois se estabelece uma comparação implícita entre copo e água.","Metonímia.","classifica metonímia como metáfora")
G(10,"confusao_instituto",3,"A catacrese é a metáfora já incorporada à língua, que perdeu o caráter de novidade e supre a falta de termo próprio, como em 'pé da mesa' e 'braço da cadeira'.","A catacrese é a figura em que se exagera uma ideia, como em 'Estou morrendo de fome'.","Catacrese.","confunde catacrese com hipérbole")
G(10,"confusao_instituto",3,"A sinestesia consiste na mistura de sensações de ordens diferentes, como em 'voz doce' e 'cor quente'.","A sinestesia consiste na atribuição de qualidades humanas a seres inanimados, como em 'o vento sussurrava'.","Sinestesia.","confunde sinestesia com prosopopeia")
G(10,"confusao_instituto",3,"A prosopopeia, ou personificação, consiste em atribuir ações, sentimentos ou qualidades humanas a seres inanimados ou irracionais, como em 'o vento sussurrava'.","A prosopopeia consiste na mistura de sensações de ordens diferentes, como em 'voz doce'.","Prosopopeia.","confunde prosopopeia com sinestesia")
G(10,"confusao_instituto",3,"A antítese é a oposição de ideias ou palavras, como em 'amor e ódio'; o paradoxo é a afirmação de ideias aparentemente contraditórias que, no entanto, produzem sentido.","A antítese é a afirmação de ideias aparentemente contraditórias que produzem sentido; o paradoxo é a simples oposição de palavras, como em 'amor e ódio'.","Antítese e paradoxo.","inverte antítese e paradoxo")
G(10,"caso_concreto",3,"A expressão 'silêncio ensurdecedor' é oxímoro, pois reúne em uma só expressão termos de sentidos contraditórios.","A expressão 'silêncio ensurdecedor' é antítese, pois opõe duas ideias em orações distintas.","Oxímoro.","classifica oxímoro como antítese")
G(10,"confusao_instituto",3,"A hipérbole é o exagero intencional de uma ideia, ao passo que o eufemismo é a suavização de uma ideia desagradável, como em 'ele nos deixou' para 'ele morreu'.","A hipérbole é a suavização de uma ideia desagradável, ao passo que o eufemismo é o exagero intencional, como em 'Estou morrendo de fome'.","Hipérbole e eufemismo.","inverte hipérbole e eufemismo")
G(10,"confusao_instituto",3,"A ironia consiste em dizer o contrário do que se pensa, com intenção crítica ou humorística, e depende do contexto para ser compreendida.","A ironia consiste em dizer exatamente o que se pensa, sem sentido figurado, e independe do contexto.","Ironia.","inverte ironia")
G(10,"confusao_instituto",3,"A litotes consiste em afirmar uma ideia por meio da negação do seu contrário, como em 'não é bonita' para 'é feia'.","A litotes consiste em exagerar uma ideia, como em 'Esperei uma eternidade'.","Litotes.","confunde litotes com hipérbole")
G(10,"confusao_instituto",3,"A elipse é a omissão de um termo que se subentende pelo contexto, ao passo que o zeugma é a omissão de um termo já expresso anteriormente.","A elipse é a omissão de um termo já expresso anteriormente, ao passo que o zeugma é a omissão de um termo que se subentende pelo contexto.","Elipse e zeugma.","inverte elipse e zeugma")
G(10,"confusao_instituto",3,"O polissíndeto é a repetição de conectivos, em geral a conjunção 'e', e o assíndeto é a ausência de conectivos entre os termos ou orações.","O polissíndeto é a ausência de conectivos entre os termos ou orações, e o assíndeto é a repetição de conectivos.","Polissíndeto e assíndeto.","inverte polissíndeto e assíndeto")
G(10,"confusao_instituto",3,"A silepse é a concordância feita com a ideia, e não com a forma gramatical, e pode ser de gênero, de número ou de pessoa.","A silepse é a repetição de consoantes ao longo de um verso ou frase, para obter efeito sonoro.","Silepse.","confunde silepse com aliteração")
G(10,"confusao_instituto",3,"A aliteração é a repetição de sons consonantais e a assonância é a repetição de sons vocálicos, ambas figuras de som.","A aliteração é a repetição de sons vocálicos e a assonância é a repetição de sons consonantais, ambas figuras de sintaxe.","Figuras de som.","inverte aliteração e assonância; troca categoria")
G(10,"confusao_instituto",3,"A anáfora, como figura de repetição, consiste no retorno da mesma palavra ou expressão no início de versos ou frases sucessivas, o que a distingue da anáfora como recurso de coesão referencial.","A anáfora, como figura de repetição, consiste na antecipação de um termo que será dito depois no texto, o que a identifica com a catáfora.","Anáfora (figura).","confunde anáfora com catáfora")
G(10,"confusao_instituto",3,"A apóstrofe consiste na invocação ou chamamento dirigido a um interlocutor, real ou imaginário, como em 'Ó mar, que tantos segredos guardas!'.","A apóstrofe consiste na omissão de um termo recuperável pelo contexto, como em 'Fui ao plenário e votei'.","Apóstrofe.","confunde apóstrofe com elipse")
G(10,"caso_concreto",4,"A expressão 'o Rei do Futebol' para designar Pelé é exemplo de antonomásia, pois substitui o nome próprio por um epíteto que o caracteriza.","A expressão 'o Rei do Futebol' para designar Pelé é exemplo de catacrese, pois supre a falta de um termo próprio na língua.","Antonomásia.","classifica antonomásia como catacrese")
G(10,"caso_concreto",4,"Em 'Pedimos o pão nosso de cada dia', a palavra 'pão' representa o alimento em geral, em sinédoque, que toma a parte pelo todo.","Em 'Pedimos o pão nosso de cada dia', a palavra 'pão' representa o alimento em geral, em antítese, que opõe o pão a outros alimentos.","Sinédoque.","classifica sinédoque como antítese")
G(10,"excecao_omitida",3,"As figuras de linguagem não são exclusivas do texto literário, pois aparecem também na publicidade, no discurso político e na fala cotidiana.","As figuras de linguagem são exclusivas do texto literário e nunca aparecem na publicidade, no discurso político ou na fala cotidiana.","Figuras e gêneros.","restringe ao literário")
G(10,"excecao_omitida",3,"Na retórica clássica, o discurso se organiza em exórdio, narração, confirmação, refutação e peroração.","Na retórica clássica, o discurso se organiza em introdução, desenvolvimento e conclusão, e as demais partes são dispensáveis.","Partes do discurso.","reduz as partes")
G(10,"caso_concreto",4,"O trecho 'Vim, vi, venci' exemplifica o assíndeto, pela ausência de conectivos entre as orações, que dá ritmo e rapidez ao enunciado.","O trecho 'Vim, vi, venci' exemplifica o polissíndeto, pela repetição de conectivos entre as orações.","Assíndeto.","classifica assíndeto como polissíndeto")
G(10,"confusao_instituto",3,"O anacoluto é a quebra da estrutura sintática da frase, em que um termo inicial fica sem função sintática na sequência, como em 'Eu, parece-me que ninguém me ouviu'.","O anacoluto é a inversão da ordem direta dos termos da oração, sem quebra de estrutura sintática, como em 'De sua vida cuidava ele'.","Anacoluto.","confunde anacoluto com hipérbato")
G(10,"confusao_instituto",3,"O pleonasmo é o reforço de uma ideia por repetição, que pode ser vicioso, quando redundante sem valor expressivo, ou literário, quando enfático, como em 'Vi com meus próprios olhos'.","O pleonasmo é a omissão de um termo que se subentende, e nunca tem valor expressivo.","Pleonasmo.","confunde pleonasmo com elipse")
G(10,"confusao_instituto",3,"A perífrase, ou circunlocução, designa um ser por meio de uma expressão que lhe aponta características, como em 'a Cidade Maravilhosa' para o Rio de Janeiro.","A perífrase consiste na substituição do nome por uma única palavra de sentido contrário, como em 'a Cidade Maravilhosa' para o Rio de Janeiro.","Perífrase.","redefine perífrase")
G(10,"excecao_omitida",3,"A gradação é a figura que apresenta ideias em progressão, ascendente ou descendente, de intensidade crescente ou decrescente.","A gradação é a figura que apresenta ideias sem qualquer ordem de intensidade ou progressão.","Gradação.","nega progressão")
# ---- 11 comunicações oficiais
G(11,"excecao_omitida",2,"Segundo o Manual de Redação da Presidência da República, são atributos da redação oficial a impessoalidade, a formalidade e padronização, a clareza e concisão, o uso da norma culta e a linguagem simples e direta.","Segundo o Manual de Redação da Presidência da República, a redação oficial deve privilegiar a expressão pessoal do redator, o uso de regionalismos e jargões e a linguagem rebuscada.","Manual de Redação, atributos.","inverte atributos")
G(11,"confusao_instituto",3,"Aviso, ofício e memorando seguem um mesmo padrão e diferem, essencialmente, quanto ao destinatário e à finalidade.","Aviso, ofício e memorando têm estruturas totalmente distintas entre si e não compartilham padrão de formatação.","Padrão ofício.","nega padrão único")
G(11,"confusao_instituto",3,"O memorando é a comunicação entre unidades administrativas de um mesmo órgão, ao passo que o ofício é usado para comunicações com destinatários externos, como particulares e outros Poderes.","O ofício é a comunicação entre unidades administrativas de um mesmo órgão, ao passo que o memorando é usado para comunicações com destinatários externos, como particulares e outros Poderes.","Ofício e memorando.","inverte ofício e memorando")
G(11,"confusao_instituto",3,"A exposição de motivos é dirigida ao Presidente da República para propor medida, informar sobre assunto ou submeter projeto de ato normativo.","A exposição de motivos é a comunicação entre unidades administrativas de um mesmo órgão, e não se dirige ao Presidente da República.","Exposição de motivos.","atribui função do memorando")
G(11,"confusao_instituto",4,"A mensagem é o instrumento de comunicação oficial entre os Chefes dos Poderes Públicos, notadamente a que o Presidente da República dirige ao Congresso Nacional, para encaminhar projetos de lei e dar conta da situação do país.","A mensagem é o instrumento utilizado exclusivamente na comunicação interna entre unidades de um mesmo órgão, como o memorando.","Mensagem.","atribui função do memorando")
G(11,"excecao_omitida",3,"Na estrutura do padrão ofício, o texto organiza-se em introdução, desenvolvimento e conclusão, e a introdução apresenta o objetivo da comunicação.","Na estrutura do padrão ofício, o texto dispensa a introdução, e o objetivo da comunicação só deve aparecer na conclusão.","Estrutura do texto.","omite introdução")
G(11,"confusao_instituto",3,"O fecho 'Respeitosamente,' é usado nas comunicações dirigidas a autoridades superiores, ao passo que 'Atenciosamente,' é usado para autoridades de mesma hierarquia ou inferiores.","O fecho 'Atenciosamente,' é usado nas comunicações dirigidas a autoridades superiores, ao passo que 'Respeitosamente,' é usado para autoridades de mesma hierarquia ou inferiores.","Fechos.","inverte fechos")
G(11,"caso_concreto",4,"Um chefe de seção que se dirige a um ministro em ofício deve encerrar com 'Respeitosamente,', por se tratar de autoridade superior.","Um chefe de seção que se dirige a um ministro em ofício deve encerrar com 'Atenciosamente,', pois esse fecho é obrigatório para autoridades superiores.","Fecho a autoridade superior.","inverte fecho")
G(11,"excecao_omitida",3,"Os pronomes de tratamento concordam com a terceira pessoa, ainda que se refiram à pessoa a quem se dirige a comunicação.","Os pronomes de tratamento concordam com a segunda pessoa, quando se referem à pessoa a quem se dirige a comunicação.","Concordância.","troca pessoa verbal")
G(11,"confusao_instituto",3,"Usa-se 'Vossa' quando se fala com a pessoa e 'Sua' quando se fala dela, como em 'Vossa Excelência decidiu' e 'Sua Excelência decidiu'.","Usa-se 'Sua' quando se fala com a pessoa e 'Vossa' quando se fala dela, como em 'Sua Excelência decidiu' ao dirigir-se ao ministro.","Vossa x Sua.","inverte Vossa e Sua")
G(11,"excecao_omitida",3,"O pronome 'Vossa Excelência' é usado, entre outros, para os Chefes dos Poderes, ministros, parlamentares e juízes.","O pronome 'Vossa Excelência' é usado apenas para os Chefes dos Poderes, sendo vedado seu emprego para ministros, parlamentares e juízes.","Vossa Excelência.","restringe destinatários")
G(11,"confusao_instituto",3,"O pronome 'Vossa Senhoria' é usado para as demais autoridades e para particulares, ao passo que 'Vossa Magnificência' é usado para reitores de universidades.","O pronome 'Vossa Senhoria' é usado para reitores de universidades, ao passo que 'Vossa Magnificência' é usado para particulares.","Pronomes de tratamento.","troca destinatários")
G(11,"confusao_instituto",3,"'Vossa Eminência' é o tratamento adequado aos cardeais e 'Vossa Santidade' ao Papa.","'Vossa Eminência' é o tratamento adequado ao Papa e 'Vossa Santidade' aos cardeais.","Pronomes eclesiásticos.","inverte tratamentos")
G(11,"caso_concreto",4,"Ao redigir ofício a um deputado federal, o vocativo adequado é 'Senhor Deputado,' e o pronome de tratamento 'Vossa Excelência'.","Ao redigir ofício a um deputado federal, o vocativo adequado é 'Meritíssimo Deputado,' e o pronome de tratamento 'Vossa Magnificência'.","Tratamento a parlamentar.","troca vocativo e pronome")
G(11,"excecao_omitida",3,"O vocativo 'Senhor Ministro,' é o adequado em comunicação dirigida a um Ministro de Estado.","O vocativo adequado em comunicação dirigida a um Ministro de Estado é sempre 'Ilustríssimo Senhor Doutor Ministro,'.","Vocativo.","usa vocativo inadequado")
G(11,"excecao_omitida",3,"Na estrutura do padrão ofício constam, entre outros elementos, o tipo e o número do expediente, o local e a data, o destinatário, o assunto, o texto, o fecho, a assinatura e a identificação do signatário.","Na estrutura do padrão ofício não consta o assunto, e a identificação do signatário é vedada.","Elementos do ofício.","omite elementos")
G(11,"excecao_omitida",3,"Siglas formadas por até três letras grafam-se em maiúsculas, como STF; as de mais de três letras, lidas como palavra, grafam-se com inicial maiúscula, como Anvisa.","Siglas de mais de três letras, lidas como palavra, grafam-se sempre em maiúsculas, como ANVISA, e as de até três letras, com inicial maiúscula.","Siglas.","inverte regra de grafia")
G(11,"excecao_omitida",3,"Na primeira ocorrência de uma sigla em um documento, desdobra-se seu significado por extenso, o que facilita a compreensão.","Na primeira ocorrência de uma sigla em um documento, é vedado o desdobramento por extenso, pois a sigla dispensa explicação.","Siglas na primeira ocorrência.","veda desdobramento")
G(11,"excecao_omitida",3,"Os símbolos de unidades de medida não levam ponto nem plural, como em '10 km' e '5 kg'.","Os símbolos de unidades de medida levam ponto e plural, como em '10 kms.' e '5 kgs.'.","Símbolos.","aplica ponto e plural")
G(11,"excecao_omitida",3,"As abreviaturas terminam em ponto, como 'art.' e 'Sr.'.","As abreviaturas não admitem ponto, como em 'art' e 'Sr'.","Abreviaturas.","retira ponto")
G(11,"excecao_omitida",3,"A impessoalidade na redação oficial decorre de o emissor ser o órgão ou a instituição, e não a pessoa do redator, o que afasta a expressão de opiniões pessoais.","A impessoalidade na redação oficial significa que o texto deve evitar sempre a voz passiva e o uso da terceira pessoa.","Impessoalidade.","confunde impessoalidade com regra de voz")
G(11,"excecao_omitida",3,"A formalidade e a padronização exigem tratamento respeitoso, uso adequado de pronomes de tratamento e uniformidade na apresentação dos documentos.","A formalidade e a padronização dispensam o uso de pronomes de tratamento e permitem que cada redator escolha livremente o formato dos documentos.","Formalidade e padronização.","nega padronização")
G(11,"excecao_omitida",3,"A clareza e a concisão são atributos que se complementam: o texto deve ser compreensível e dizer o necessário com o menor número de palavras possível, sem perda de sentido.","A concisão exige a supressão de dados essenciais para que o texto seja o mais curto possível, mesmo que se perca a clareza.","Clareza e concisão.","sacrifica clareza")
G(11,"excecao_omitida",3,"O texto eletrônico (e-mail) usado como comunicação oficial mantém os atributos da redação oficial, como formalidade, clareza e uso da norma culta.","O texto eletrônico (e-mail) usado como comunicação oficial dispensa os atributos da redação oficial, por se tratar de meio informal.","E-mail oficial.","nega atributos")
G(11,"excecao_omitida",3,"O Decreto 9.758/2019 tratou de formas de tratamento a serem observadas na comunicação com agentes públicos federais, e as regras do Manual de Redação convivem com ele.","O Decreto 9.758/2019 revogou integralmente o Manual de Redação e proibiu o uso de qualquer pronome de tratamento em documentos oficiais.","Decreto 9.758/2019.","exagera efeito do decreto")
# ---- 12 lógica
G(12,"excecao_omitida",2,"Proposição é toda sentença declarativa que pode ser julgada verdadeira ou falsa, e perguntas, ordens e exclamações não são proposições.","Proposição é toda sentença da língua, inclusive perguntas, ordens e exclamações, pois todas podem ser julgadas verdadeiras ou falsas.","Proposição.","inclui sentenças não declarativas")
G(12,"confusao_instituto",2,"A conjunção p ∧ q só é verdadeira se p e q forem ambas verdadeiras.","A conjunção p ∧ q é verdadeira se ao menos uma entre p e q for verdadeira.","Conjunção.","confunde conjunção e disjunção")
G(12,"confusao_instituto",2,"A disjunção inclusiva p ∨ q só é falsa quando p e q são ambas falsas.","A disjunção inclusiva p ∨ q só é falsa quando p e q são ambas verdadeiras.","Disjunção.","inverte condição de falsidade")
G(12,"excecao_omitida",3,"A disjunção exclusiva é verdadeira quando exatamente uma das proposições é verdadeira, e falsa quando ambas têm o mesmo valor lógico.","A disjunção exclusiva é verdadeira quando as duas proposições são verdadeiras, e falsa quando uma delas é falsa.","Disjunção exclusiva.","confunde com conjunção")
G(12,"confusao_instituto",3,"O condicional p → q só é falso quando p é verdadeira e q é falsa.","O condicional p → q só é falso quando p é falsa e q é verdadeira.","Condicional.","inverte caso de falsidade")
G(12,"confusao_instituto",3,"O bicondicional p ↔ q é verdadeiro quando p e q têm o mesmo valor lógico, e falso quando têm valores diferentes.","O bicondicional p ↔ q é verdadeiro quando p e q têm valores lógicos diferentes, e falso quando têm o mesmo valor.","Bicondicional.","inverte condição")
G(12,"troca_numero",3,"Uma tabela-verdade de uma proposição composta por três proposições simples distintas tem oito linhas.","Uma tabela-verdade de uma proposição composta por três proposições simples distintas tem seis linhas.","Número de linhas.","erra 2ⁿ")
G(12,"confusao_instituto",3,"Pelas leis de De Morgan, a negação de 'p e q' é equivalente a 'não p ou não q'.","Pelas leis de De Morgan, a negação de 'p e q' é equivalente a 'não p e não q'.","De Morgan.","mantém conectivo")
G(12,"confusao_instituto",3,"Pelas leis de De Morgan, a negação de 'p ou q' é equivalente a 'não p e não q'.","Pelas leis de De Morgan, a negação de 'p ou q' é equivalente a 'não p ou não q'.","De Morgan.","mantém conectivo")
G(12,"confusao_instituto",3,"A negação do condicional 'se p, então q' é equivalente a 'p e não q'.","A negação do condicional 'se p, então q' é equivalente a 'se p, então não q'.","Negação do condicional.","nega apenas o consequente")
G(12,"caso_concreto",4,"A negação de 'Se o projeto for aprovado, então será sancionado' é 'O projeto foi aprovado e não foi sancionado'.","A negação de 'Se o projeto for aprovado, então será sancionado' é 'Se o projeto não for aprovado, então não será sancionado'.","Negação do condicional.","confunde negação com inversa")
G(12,"confusao_instituto",3,"O condicional p → q é equivalente à sua contrapositiva ¬q → ¬p e à disjunção ¬p ∨ q.","O condicional p → q é equivalente à sua recíproca q → p e à sua inversa ¬p → ¬q.","Equivalências do condicional.","confunde contrapositiva com recíproca")
G(12,"caso_concreto",4,"A proposição 'Se chove, então a rua fica molhada' é equivalente a 'Se a rua não fica molhada, então não chove'.","A proposição 'Se chove, então a rua fica molhada' é equivalente a 'Se a rua fica molhada, então chove'.","Contrapositiva.","troca por recíproca")
G(12,"excecao_omitida",3,"Tautologia é a proposição composta que é sempre verdadeira, e contradição é a que é sempre falsa, quaisquer que sejam os valores lógicos das proposições simples.","Tautologia é a proposição composta que é sempre falsa, e contradição é a que é sempre verdadeira, quaisquer que sejam os valores lógicos das proposições simples.","Tautologia e contradição.","inverte conceitos")
G(12,"excecao_omitida",3,"A validade de um argumento dedutivo depende de sua forma, e não da verdade das proposições que o compõem, de modo que um argumento válido pode ter conclusão falsa se alguma premissa for falsa.","A validade de um argumento dedutivo depende da verdade de suas proposições, de modo que um argumento válido tem sempre conclusão verdadeira.","Validade de argumento.","confunde validade com verdade")
G(12,"confusao_instituto",3,"Em um argumento válido, é impossível que as premissas sejam verdadeiras e a conclusão falsa.","Em um argumento válido, é possível que as premissas sejam verdadeiras e a conclusão falsa, desde que a forma seja correta.","Argumento válido.","admite premissas verdadeiras e conclusão falsa")
G(12,"caso_concreto",4,"O argumento 'Se o processo é urgente, é incluído na pauta; o processo é urgente; logo, é incluído na pauta' tem a forma do modus ponens e é válido.","O argumento 'Se o processo é urgente, é incluído na pauta; o processo é urgente; logo, é incluído na pauta' é uma falácia da afirmação do consequente e é inválido.","Modus ponens.","classifica modus ponens como falácia")
G(12,"caso_concreto",4,"O argumento 'Se o processo é urgente, é incluído na pauta; o processo foi incluído na pauta; logo, é urgente' é falacioso, por afirmar o consequente.","O argumento 'Se o processo é urgente, é incluído na pauta; o processo foi incluído na pauta; logo, é urgente' é válido, pois tem a forma do modus ponens.","Afirmação do consequente.","trata falácia como modus ponens")
G(12,"confusao_instituto",4,"O modus tollens, forma válida, tem a estrutura: p → q; ¬q; logo ¬p.","O modus tollens, forma válida, tem a estrutura: p → q; ¬p; logo ¬q.","Modus tollens.","troca por negação do antecedente")
G(12,"confusao_instituto",3,"O silogismo hipotético tem a forma: p → q; q → r; logo p → r.","O silogismo hipotético tem a forma: p → q; r → q; logo p → r.","Silogismo hipotético.","altera encadeamento")
G(12,"confusao_instituto",3,"O silogismo disjuntivo tem a forma: p ∨ q; ¬p; logo q.","O silogismo disjuntivo tem a forma: p ∨ q; p; logo ¬q, válida para qualquer disjunção, inclusive a inclusiva.","Silogismo disjuntivo.","afirma forma inválida para disjunção inclusiva")
G(12,"confusao_instituto",3,"A negação de 'todo A é B' é 'algum A não é B'.","A negação de 'todo A é B' é 'nenhum A é B'.","Quantificadores.","confunde com contrário")
G(12,"confusao_instituto",3,"A negação de 'nenhum A é B' é 'algum A é B'.","A negação de 'nenhum A é B' é 'todo A é B'.","Quantificadores.","confunde com contrário")
G(12,"caso_concreto",4,"A negação de 'Todos os servidores compareceram' é 'Pelo menos um servidor não compareceu'.","A negação de 'Todos os servidores compareceram' é 'Nenhum servidor compareceu'.","Negação de universal.","confunde contrário e contraditório")
G(12,"excecao_omitida",3,"O princípio do terceiro excluído estabelece que uma proposição é verdadeira ou falsa, não havendo terceira possibilidade.","O princípio do terceiro excluído estabelece que uma proposição pode ser, ao mesmo tempo, verdadeira e falsa.","Terceiro excluído.","confunde com contradição")
G(12,"excecao_omitida",3,"O princípio da não contradição estabelece que uma proposição não pode ser verdadeira e falsa ao mesmo tempo.","O princípio da não contradição estabelece que uma proposição pode ser verdadeira e falsa ao mesmo tempo, desde que em momentos distintos.","Não contradição.","nega o princípio")
# ---- 13 LC 95
G(13,"excecao_omitida",2,"A LC 95/1998 dispõe sobre a elaboração, a redação, a alteração e a consolidação das leis, nos termos do parágrafo único do art. 59 da Constituição Federal.","A LC 95/1998 dispõe sobre o processo legislativo, regulando a iniciativa, a sanção, o veto e os quóruns de votação das leis.","LC 95/1998, ementa.","atribui conteúdo de processo legislativo",lei=True)
G(13,"excecao_omitida",3,"As disposições da LC 95/1998 aplicam-se também às medidas provisórias e, no que couber, aos decretos e aos demais atos de regulamentação expedidos por órgãos do Poder Executivo.","As disposições da LC 95/1998 aplicam-se somente às leis ordinárias e complementares, não alcançando medidas provisórias nem decretos.","LC 95/1998, art. 1º, parágrafo único.","restringe campo de aplicação",lei=True)
G(13,"confusao_instituto",3,"A lei será estruturada em três partes básicas: a preliminar, a normativa e a final.","A lei será estruturada em quatro partes básicas: a preliminar, a normativa, a final e a de motivação.","LC 95/1998, art. 3º.","acrescenta parte inexistente",lei=True)
G(13,"confusao_instituto",3,"Integram a parte preliminar da lei a epígrafe, a ementa, o preâmbulo, o enunciado do objeto e a indicação do âmbito de aplicação das disposições normativas.","Integram a parte preliminar da lei as disposições transitórias, a cláusula de vigência e a cláusula de revogação.","LC 95/1998, art. 3º, I.","troca partes",lei=True)
G(13,"confusao_instituto",3,"Integram a parte final da lei as disposições pertinentes às medidas necessárias à implementação das normas substantivas, as disposições transitórias, a cláusula de vigência e a cláusula de revogação, quando couber.","Integram a parte final da lei a epígrafe, a ementa e o preâmbulo.","LC 95/1998, art. 3º, III.","troca partes",lei=True)
G(13,"excecao_omitida",3,"A epígrafe da lei, grafada em caracteres maiúsculos, é formada pelo título designativo da espécie normativa, pelo número respectivo e pelo ano de promulgação.","A epígrafe da lei, grafada em caracteres minúsculos, é formada apenas pelo título designativo da espécie normativa, sem número nem ano.","LC 95/1998, art. 4º.","altera forma da epígrafe",lei=True)
G(13,"confusao_instituto",3,"A ementa explicita, de modo conciso e sob a forma de título, o objeto da lei.","O preâmbulo explicita, de modo conciso e sob a forma de título, o objeto da lei, enquanto a ementa indica o órgão competente e a base legal.","LC 95/1998, arts. 5º e 6º.","troca ementa e preâmbulo",lei=True)
G(13,"confusao_instituto",3,"O preâmbulo indica o órgão ou a instituição competente para a prática do ato e sua base legal.","A ementa indica o órgão ou a instituição competente para a prática do ato e sua base legal.","LC 95/1998, art. 6º.","troca ementa e preâmbulo",lei=True)
G(13,"excecao_omitida",3,"Excetuadas as codificações, cada lei tratará de um único objeto, e a lei não conterá matéria estranha a seu objeto ou a este não vinculada por afinidade, pertinência ou conexão.","Cada lei poderá tratar de mais de um objeto, desde que todos estejam enumerados no primeiro artigo, inclusive em leis que não sejam codificações.","LC 95/1998, art. 7º, I e II.","admite mais de um objeto",lei=True)
G(13,"excecao_omitida",4,"O mesmo assunto não poderá ser disciplinado por mais de uma lei, exceto quando a subsequente se destine a complementar lei considerada básica, vinculando-se a esta por remissão expressa.","O mesmo assunto poderá ser disciplinado por mais de uma lei, sem necessidade de remissão expressa, desde que a lei posterior revogue a anterior de forma tácita.","LC 95/1998, art. 7º, IV.","afasta remissão expressa",lei=True)
G(13,"excecao_omitida",3,"O âmbito de aplicação da lei será estabelecido de forma tão específica quanto o possibilite o conhecimento técnico ou científico da área respectiva.","O âmbito de aplicação da lei será sempre estabelecido de forma genérica, para que a norma alcance o maior número possível de situações.","LC 95/1998, art. 7º, III.","inverte critério",lei=True)
G(13,"excecao_omitida",3,"A vigência da lei será indicada de forma expressa e de modo a contemplar prazo razoável para que dela se tenha amplo conhecimento, reservada a cláusula 'entra em vigor na data de sua publicação' para as leis de pequena repercussão.","A cláusula 'entra em vigor na data de sua publicação' deve ser adotada em todas as leis, independentemente de sua repercussão, pois assegura a vigência imediata.","LC 95/1998, art. 8º.","generaliza cláusula de vigência imediata",lei=True)
G(13,"confusao_instituto",4,"Na contagem do prazo de vacância, incluem-se a data da publicação e o último dia do prazo, e a lei entra em vigor no dia subsequente à consumação integral do prazo.","Na contagem do prazo de vacância, excluem-se a data da publicação e o último dia do prazo, e a lei entra em vigor no próprio último dia do prazo.","LC 95/1998, art. 8º, § 1º.","inverte regra de contagem",lei=True)
G(13,"excecao_omitida",3,"As leis que estabeleçam período de vacância devem utilizar a cláusula 'esta lei entra em vigor após decorridos (número de dias) de sua publicação oficial'.","As leis que estabeleçam período de vacância devem utilizar a cláusula 'esta lei entra em vigor na data de sua publicação, produzindo efeitos após o prazo previsto'.","LC 95/1998, art. 8º, § 2º.","altera cláusula de vacância",lei=True)
G(13,"excecao_omitida",3,"A cláusula de revogação deverá enumerar, expressamente, as leis ou disposições legais revogadas.","A cláusula de revogação deverá utilizar, sempre, a expressão genérica 'revogam-se as disposições em contrário', vedada a enumeração das normas revogadas.","LC 95/1998, art. 9º.","inverte regra de revogação",lei=True)
G(13,"troca_numero",3,"A unidade básica de articulação dos textos legais é o artigo, indicado pela abreviatura 'Art.', seguida de numeração ordinal até o nono e cardinal a partir deste.","A unidade básica de articulação dos textos legais é o parágrafo, indicado pelo sinal '§', seguido de numeração cardinal em todos os casos.","LC 95/1998, art. 10, I.","troca unidade básica",lei=True)
G(13,"confusao_instituto",3,"Os artigos desdobram-se em parágrafos ou incisos, os parágrafos em incisos, os incisos em alíneas e as alíneas em itens.","Os artigos desdobram-se em alíneas, as alíneas em incisos, os incisos em parágrafos e os parágrafos em itens.","LC 95/1998, art. 10, II.","inverte hierarquia",lei=True)
G(13,"confusao_instituto",3,"Os incisos são representados por algarismos romanos, as alíneas por letras minúsculas e os itens por algarismos arábicos.","Os incisos são representados por letras minúsculas, as alíneas por algarismos romanos e os itens por algarismos arábicos.","LC 95/1998, art. 10, IV.","troca representações",lei=True)
G(13,"excecao_omitida",3,"Quando existe apenas um parágrafo, usa-se a expressão 'parágrafo único' por extenso, em vez do sinal '§'.","Quando existe apenas um parágrafo, usa-se o sinal '§ 1º', seguido da indicação 'único'.","LC 95/1998, art. 10, III.","altera expressão do parágrafo único",lei=True)
G(13,"confusao_instituto",3,"Os Capítulos, Títulos, Livros e Partes são grafados em letras maiúsculas e identificados por algarismos romanos, ao passo que as Subseções e Seções são identificadas em algarismos romanos, grafadas em letras minúsculas e postas em negrito.","Os Capítulos, Títulos, Livros e Partes são grafados em letras minúsculas e identificados por algarismos arábicos, ao passo que as Subseções e Seções são grafadas em letras maiúsculas.","LC 95/1998, art. 10, VI e VII.","troca grafia",lei=True)
G(13,"confusao_instituto",3,"O agrupamento de artigos pode constituir Subseções; o de Subseções, a Seção; o de Seções, o Capítulo; o de Capítulos, o Título; o de Títulos, o Livro; e o de Livros, a Parte.","O agrupamento de artigos pode constituir Capítulos; o de Capítulos, a Seção; o de Seções, a Subseção; o de Subseções, o Título; e o de Títulos, o Livro.","LC 95/1998, art. 10, V.","inverte agrupamentos",lei=True)
G(13,"excecao_omitida",3,"As disposições normativas serão redigidas com clareza, precisão e ordem lógica.","As disposições normativas serão redigidas com ênfase na expressividade, na variedade vocabular e no estilo elaborado.","LC 95/1998, art. 11.","inverte princípios",lei=True)
G(13,"excecao_omitida",3,"Para obter clareza, deve-se usar as palavras em seu sentido comum, salvo quando a norma versar sobre assunto técnico, hipótese em que se empregará a nomenclatura própria da área.","Para obter clareza, deve-se usar sempre termos técnicos e raros, ainda que a norma não verse sobre assunto técnico, para conferir maior elegância ao texto.","LC 95/1998, art. 11, I, a.","inverte regra de clareza",lei=True)
G(13,"excecao_omitida",3,"Para obter clareza, devem ser usadas frases curtas e concisas e orações construídas na ordem direta, evitando-se preciosismo, neologismo e adjetivações dispensáveis.","Para obter clareza, devem ser usadas frases longas e orações em ordem inversa, valorizando-se o preciosismo e o neologismo.","LC 95/1998, art. 11, I, b e c.","inverte regra de clareza",lei=True)
G(13,"excecao_omitida",3,"Deve-se buscar a uniformidade do tempo verbal em todo o texto das normas legais, dando preferência ao tempo presente ou ao futuro simples do presente.","Deve-se alternar os tempos verbais ao longo do texto das normas legais, dando preferência ao pretérito perfeito.","LC 95/1998, art. 11, I, d.","inverte regra do tempo verbal",lei=True)
G(13,"excecao_omitida",3,"Para obter precisão, deve-se expressar a ideia, quando repetida no texto, por meio das mesmas palavras, evitando o emprego de sinonímia com propósito meramente estilístico.","Para obter precisão, deve-se variar as palavras sempre que a ideia for repetida no texto, empregando sinônimos com propósito estilístico.","LC 95/1998, art. 11, II, b.","inverte regra da sinonímia",lei=True)
G(13,"excecao_omitida",3,"Devem ser escolhidos termos que tenham o mesmo sentido e significado na maior parte do território nacional, evitando-se o uso de expressões locais ou regionais.","Devem ser preferidas expressões locais ou regionais, para aproximar a norma da realidade de cada Estado.","LC 95/1998, art. 11, II, d.","inverte regra de expressões regionais",lei=True)
G(13,"excecao_omitida",3,"Devem ser usadas apenas siglas consagradas pelo uso, e a sigla somente será usada depois da primeira referência por extenso.","Podem ser criadas novas siglas a cada lei, e a sigla deve ser usada desde a primeira referência, sem desdobramento por extenso.","LC 95/1998, art. 11, II, e.","inverte regra de siglas",lei=True)
G(13,"excecao_omitida",3,"Quaisquer referências feitas, no texto, a números e percentuais devem ser grafadas por extenso.","Referências a números e percentuais devem ser grafadas em algarismos, em todo o texto legal, para assegurar precisão.","LC 95/1998, art. 11, II, f.","inverte regra de números",lei=True)
G(13,"excecao_omitida",3,"Deve-se indicar expressamente o dispositivo objeto de remissão, em vez de usar as expressões 'anterior', 'seguinte' ou equivalentes.","Para fazer remissão a outro dispositivo, devem ser usadas as expressões 'anterior', 'seguinte' ou equivalentes, em vez da indicação expressa do dispositivo.","LC 95/1998, art. 11, II, g.","inverte regra de remissão",lei=True)
G(13,"confusao_instituto",3,"Os aspectos complementares à norma enunciada no caput do artigo e as exceções à regra por este estabelecida devem ser expressos por meio de parágrafos.","Os aspectos complementares à norma do caput do artigo e as exceções à regra devem ser expressos por meio de incisos, e as enumerações por parágrafos.","LC 95/1998, art. 11, III, c e d.","troca parágrafos e incisos",lei=True)
G(13,"excecao_omitida",3,"O conteúdo de cada artigo da lei deve ser restrito a um único assunto ou princípio.","Cada artigo da lei pode reunir vários assuntos ou princípios, desde que relacionados ao objeto da lei.","LC 95/1998, art. 11, III, b.","admite pluralidade de assuntos",lei=True)
G(13,"excecao_omitida",3,"A alteração da lei será feita mediante reprodução integral em novo texto, quando se tratar de alteração considerável, mediante revogação parcial ou, nos demais casos, por substituição do dispositivo alterado ou acréscimo de dispositivo novo.","A alteração da lei será feita sempre mediante reprodução integral em novo texto, vedadas a revogação parcial e a substituição de dispositivos.","LC 95/1998, art. 12.","admite uma única forma de alteração",lei=True)
G(13,"excecao_omitida",3,"É vedada, mesmo quando recomendável, a renumeração de artigos, parágrafos, incisos, alíneas ou itens, devendo ser utilizado o mesmo número do dispositivo imediatamente anterior, seguido de letra maiúscula, em ordem alfabética.","É permitida a renumeração de artigos, parágrafos, incisos, alíneas ou itens sempre que isso tornar o texto mais organizado, cabendo à lei alteradora indicar a nova numeração.","LC 95/1998, art. 12, III.","permite renumeração",lei=True)
G(13,"caso_concreto",4,"Para acrescentar um novo artigo entre os arts. 5º e 6º de uma lei, usa-se a numeração 'Art. 5º-A', sem renumerar os demais artigos.","Para acrescentar um novo artigo entre os arts. 5º e 6º de uma lei, renumeram-se os artigos seguintes, de modo que o novo artigo passe a ser o 6º.","LC 95/1998, art. 12, III.","permite renumeração",lei=True)
G(13,"excecao_omitida",3,"É vedado o aproveitamento do número de dispositivo revogado, vetado, declarado inconstitucional pelo Supremo Tribunal Federal ou de execução suspensa pelo Senado Federal.","Pode ser aproveitado o número de dispositivo revogado ou vetado, para que a numeração do texto não fique com lacunas.","LC 95/1998, art. 12, III.","permite aproveitamento de número",lei=True)
G(13,"excecao_omitida",3,"A identificação do dispositivo que recebeu nova redação faz-se com a sigla NR, em maiúsculas e entre parênteses, ao final.","A identificação do dispositivo que recebeu nova redação faz-se com a sigla NR, em minúsculas e no início do dispositivo.","LC 95/1998, art. 12.","altera forma do NR",lei=True)
G(13,"excecao_omitida",3,"A consolidação consiste na integração de todas as leis pertinentes a determinada matéria em um único diploma legal, revogando-se formalmente as leis incorporadas, sem modificação do alcance nem interrupção da força normativa dos dispositivos consolidados.","A consolidação consiste na alteração do mérito das leis pertinentes a determinada matéria, com criação de novos direitos e obrigações e supressão das normas de conteúdo diverso.","LC 95/1998, art. 13, § 1º.","admite inovação",lei=True)
G(13,"excecao_omitida",4,"Na consolidação, preservado o conteúdo normativo original dos dispositivos, podem ser feitas alterações como a fusão de disposições repetitivas, a atualização da denominação de órgãos e a homogeneização terminológica.","Na consolidação, é vedada qualquer alteração formal do texto, inclusive a fusão de disposições repetitivas e a atualização da denominação de órgãos.","LC 95/1998, art. 13, § 2º.","veda alterações formais",lei=True)
G(13,"excecao_omitida",3,"Eventual inexatidão formal de norma elaborada mediante processo legislativo regular não constitui escusa válida para o seu descumprimento.","A inexatidão formal de norma elaborada mediante processo legislativo regular constitui escusa válida para o seu descumprimento.","LC 95/1998, art. 18.","inverte regra do art. 18",lei=True)
G(13,"excecao_omitida",3,"O desrespeito às regras de técnica legislativa da LC 95/1998, por si só, não torna inválida a lei aprovada em processo legislativo regular, cabendo, em geral, correção por lei posterior.","O desrespeito às regras de técnica legislativa da LC 95/1998 torna, por si só, inconstitucional e inválida qualquer lei aprovada em processo legislativo regular.","LC 95/1998, art. 18.","exagera efeito do descumprimento",lei=True)
G(13,"confusao_instituto",4,"A LC 95/1998 foi editada com fundamento no parágrafo único do art. 59 da Constituição Federal e foi alterada pela LC 107/2001.","A LC 95/1998 foi editada com fundamento no art. 61 da Constituição Federal, que trata da iniciativa das leis, e nunca sofreu alterações.","LC 95/1998; LC 107/2001.","troca fundamento e nega alterações",lei=True)
G(13,"excecao_omitida",3,"As regras da LC 95/1998 aplicam-se às leis e aos atos normativos do art. 59 da Constituição Federal, e não substituem o regimento interno das Casas legislativas quanto ao processo legislativo.","A LC 95/1998 regula o processo legislativo das Casas do Congresso Nacional e substitui os respectivos regimentos internos nesse ponto.","LC 95/1998.","confunde técnica com processo legislativo",lei=True)
G(13,"excecao_omitida",3,"A numeração do artigo é ordinal até o nono e cardinal a partir deste, de modo que se escreve 'Art. 9º' e 'Art. 10'.","A numeração do artigo é ordinal até o décimo e cardinal a partir deste, de modo que se escreve 'Art. 10º' e 'Art. 11'.","LC 95/1998, art. 10, I.","altera ponto de corte",lei=True)
G(13,"excecao_omitida",3,"Os parágrafos são representados pelo sinal gráfico '§', seguido de numeração ordinal até o nono e cardinal a partir deste.","Os parágrafos são representados pela abreviatura 'Par.', seguida de numeração cardinal em todos os casos.","LC 95/1998, art. 10, III.","altera representação",lei=True)
G(13,"excecao_omitida",3,"A parte normativa da lei compreende o texto das normas de conteúdo substantivo relacionadas com a matéria regulada.","A parte normativa da lei compreende apenas a ementa e o preâmbulo, e as normas de conteúdo substantivo integram a parte final.","LC 95/1998, art. 3º, II.","troca partes",lei=True)
G(13,"caso_concreto",4,"Uma lei que se limita a dispor sobre aposentadoria de servidores e, no último artigo, inclui regra sobre licitações sem relação com o tema viola o princípio de que a lei não conterá matéria estranha a seu objeto.","Uma lei que se limita a dispor sobre aposentadoria de servidores e, no último artigo, inclui regra sobre licitações sem relação com o tema respeita a LC 95/1998, pois o texto pode reunir assuntos diversos em uma mesma lei.","LC 95/1998, art. 7º, II.","admite matéria estranha",lei=True)
G(13,"excecao_omitida",3,"Os decretos e demais atos de regulamentação do Poder Executivo observam as regras da LC 95/1998 no que couber.","Os decretos e demais atos de regulamentação do Poder Executivo estão isentos das regras da LC 95/1998.","LC 95/1998, art. 1º, parágrafo único.","isenta decretos",lei=True)
G(13,"excecao_omitida",3,"A organização das disposições por agrupamentos (Subseções, Seções, Capítulos etc.) deve reunir apenas as disposições relacionadas com o objeto da lei.","A organização das disposições por agrupamentos pode reunir disposições alheias ao objeto da lei, desde que sob o mesmo capítulo.","LC 95/1998, art. 11, III, a.","admite disposições alheias",lei=True)
G(13,"excecao_omitida",3,"As discriminações e enumerações devem ser feitas por meio dos incisos, alíneas e itens.","As discriminações e enumerações devem ser feitas por meio de parágrafos, vedado o uso de incisos, alíneas e itens.","LC 95/1998, art. 11, III, d.","inverte regra de enumeração",lei=True)
